function process(){
  const v=document.getElementById('inp').value.trim();
  if(!v){document.getElementById('out').textContent='Enter a number';return;}
  const n=parseFloat(v);if(isNaN(n)){document.getElementById('out').textContent='Invalid';return;}
  document.getElementById('out').innerHTML='<div class="text-lg font-bold text-brand-400">'+n.toExponential(6)+'</div><div class="text-sm text-surface-400">Standard: '+n.toLocaleString('en-US',{maximumFractionDigits:10})+'</div>';
}

function gcf(a,b){while(b){[a,b]=[b,a%b]}return Math.abs(a)}
function process(){
  const p=document.getElementById('inp').value.split(/[:\/]/);
  if(p.length!==2){document.getElementById('out').textContent='Enter ratio like 12:8';return;}
  const a=parseInt(p[0]),b=parseInt(p[1]);if(isNaN(a)||isNaN(b)||b===0){document.getElementById('out').textContent='Invalid';return;}
  const g=gcf(a,b);document.getElementById('out').innerHTML='<div class="text-xl font-bold text-brand-400">'+a/g+' : '+b/g+'</div>';
}

function process(){
  const v=document.getElementById('inp').value.split(/[,\s]+/).map(Number);
  if(v.length<3||v.some(isNaN)){document.getElementById('out').textContent='Format: a, b, c (solve a:b = c:x)';return;}
  document.getElementById('out').innerHTML='<div class="text-lg">'+v[0]+' : '+v[1]+' = '+v[2]+' : <span class="text-xl font-bold text-brand-400">'+(v[2]*v[1]/v[0]).toFixed(4)+'</span></div>';
}

function process(){
  const v=document.getElementById('inp').value.split(/[,\s]+/).map(Number);
  if(v.length<3||v.some(isNaN)){document.getElementById('out').textContent='Format: a, b, c (ax²+bx+c=0)';return;}
  if(v[0]===0){document.getElementById('out').textContent='a cannot be 0';return;}
  const d=v[1]*v[1]-4*v[0]*v[2];
  if(d>0){const r1=(-v[1]+Math.sqrt(d))/(2*v[0]),r2=(-v[1]-Math.sqrt(d))/(2*v[0]);document.getElementById('out').innerHTML='<div class="text-brand-400">Two real roots:</div><div class="text-lg font-bold">x₁='+r1.toFixed(4)+'</div><div class="text-lg font-bold">x₂='+r2.toFixed(4)+'</div>';}
  else if(d===0){document.getElementById('out').innerHTML='<div class="text-brand-400">One real root:</div><div class="text-lg font-bold">x='+(-v[1]/(2*v[0])).toFixed(4)+'</div>';}
  else{const r=-v[1]/(2*v[0]),im=Math.sqrt(-d)/(2*v[0]);document.getElementById('out').innerHTML='<div class="text-brand-400">Complex roots:</div><div class="text-lg font-bold">x='+r.toFixed(4)+' ± '+im.toFixed(4)+'i</div>';}
}

function process(){
  const v=document.getElementById('inp').value.split(/[,\s]+/).map(Number);
  if(v.length<2||v.some(isNaN)){document.getElementById('out').textContent='Format: base, exponent';return;}
  const r=Math.pow(v[0],v[1]);
  document.getElementById('out').innerHTML='<div class="text-xl font-bold text-brand-400">'+v[0]+'<sup>'+v[1]+'</sup> = '+r.toFixed(6)+'</div>';
}

function process(){
  const t=document.getElementById('inp').value.trim();if(!t){document.getElementById('out').textContent='Enter text';return;}
  const w=t.split(/\s+/).filter(x=>x),s=t.split(/[.!?]+/).filter(x=>x.trim()),syl=w.reduce((a,x)=>{const c=x.toLowerCase().replace(/[^a-z]/g,'');return a+Math.max(1,(c.match(/[aeiouy]/g)||[]).length)},0),wc=w.length,sc=s.length||1,fr=206.835-1.015*(wc/sc)-84.6*(syl/wc);
  document.getElementById('out').innerHTML='<div class="text-xl font-bold text-brand-400">Level: '+(fr>90?'5th grade':fr>80?'6th':fr>70?'7th':fr>60?'8-9th':fr>50?'10-12th':fr>30?'College':'College grad')+'</div><div class="text-sm mt-1">'+wc+' words · '+sc+' sentences · Score: '+Math.round(fr)+'</div>';
}

function process(){
  const t=document.getElementById('inp').value.replace(/[^a-zA-Z0-9]/g,'').toLowerCase();if(!t){document.getElementById('out').textContent='Enter text';return;}
  const p=t===t.split('').reverse().join('');
  document.getElementById('out').innerHTML='<div class="text-xl font-bold '+(p?'text-green-400':'text-red-400')+'">'+(p?'✓ Palindrome!':'✗ Not palindrome')+'</div>';
}

function process(){
  const v=document.getElementById('inp').value.split('|').map(s=>s.replace(/[^a-zA-Z]/g,'').toLowerCase().split('').sort().join(''));
  if(v.length<2){document.getElementById('out').textContent='Format: word1 | word2';return;}
  document.getElementById('out').innerHTML='<div class="text-xl font-bold '+(v[0]===v[1]?'text-green-400':'text-red-400')+'">'+(v[0]===v[1]?'✓ Anagrams!':'✗ Not anagrams')+'</div>';
}

function process(){
  const t=document.getElementById('inp').value;if(!t){document.getElementById('out').textContent='Enter text';return;}
  const f={};for(const c of t)f[c]=(f[c]||0)+1;
  const s=Object.entries(f).sort((a,b)=>b[1]-a[1]).slice(0,15);
  document.getElementById('out').innerHTML='<table class="w-full text-xs">'+s.map(([c,n])=>'<tr><td class="py-1 pr-3 font-mono">'+(c===' '?'␣':c==='\n'?'↵':c)+'</td><td class="py-1">'+n+'</td><td class="py-1"><div class="bg-brand-500/30 h-2 rounded" style="width:'+(n/s[0][1]*100)+'%"></div></td></tr>').join('')+'</table>';
}

function process(){
  const t=document.getElementById('inp').value,w=parseInt(document.getElementById('inp').dataset.width)||80;if(!t){document.getElementById('out').textContent='Enter text';return;}
  let r='',l='';for(const wd of t.split(' ')){if(l&&l.length+wd.length+1>w){r+=l+'\n';l=wd}else l=l?(l+' '+wd):wd}r+=l;
  document.getElementById('out').innerHTML='<pre class="font-mono text-xs">'+r.replace(/</g,'&lt;')+'</pre>';
}
